mapper.update:
UPDATE ddc_config_process_receipt
SET applied_revision = #{row.appliedRevision}, applied_digest = #{row.appliedDigest},
    result = #{row.result}, reason_code = #{row.reasonCode}, reason_message = NULL,
    report_seq = #{row.reportSeq}, receipt_digest = #{row.receiptDigest}, reported_at = #{row.reportedAt},
    applied_at = #{row.appliedAt},
    last_received_at = GREATEST(last_received_at, update_time, create_time, #{row.lastReceivedAt}, #{row.updateTime}),
    update_user_id = #{row.updateUserId},
    update_time = #{row.updateTime}, version = version + 1
WHERE tenant_id = #{row.tenantId} AND id = #{row.id} AND version = #{expectedVersion}
  AND report_seq = #{expectedSeq} AND report_seq < #{row.reportSeq} AND deleted_at IS NULL
  AND config_id = #{row.configId} AND config_revision = #{row.configRevision}
  AND target_binding_id = #{row.targetBindingId} AND target_revision = #{row.targetRevision}
  AND cluster_id = #{row.clusterId} AND pod_uid = #{row.podUid} AND container_id = #{row.containerId} AND boot_id = #{row.bootId}
  AND workload_uid = #{row.workloadUid} AND k8s_namespace = #{row.k8sNamespace} AND container_name = #{row.containerName}
  AND content_digest = #{row.contentDigest} AND restart_digest = #{row.restartDigest}
  AND (result NOT IN ('APPLIED', 'DISABLED_APPLIED') OR result = #{row.result})
  AND (result <> 'RESTART_REQUIRED' OR #{row.result} = 'RESTART_REQUIRED')

